import get from 'lodash/get'
import { useCallback, useEffect, useRef } from 'react'
import InnerForm from '../../InnerForm'
import { getAddrPostalFormData } from '../helper'
import { AddressFormStyle } from './index.style'
import { resetError, useErrorContextValue, useLoaderContextValue, updateLoader } from '@pasarpolis/common-react-hooks'
import { useGetCityList, useGetProvinceList, useValidatePostalCode } from '../state/hooks/useAddressForm'
import ShowSnackbar from '../../ShowNotification'
import isEmpty from 'lodash/isEmpty'
import { typeValid } from '../../../helpers/validations'

function AddressFormContainer ({ onAddressChange, ...props }) {
  const { handleGetAddressSubmit, addressType, address = {}, labels = {} } = props

  const addrPostalSubmit = useRef()
  const citiesRef = useRef(null)
  const initialRender = useRef(true)
  const that = useRef({
    isAddressError: false
  })
  const [, validatePostalCodeReq] = useValidatePostalCode()

  const [{ getProvinceListData = [] }, getProvinceListRequest] = useGetProvinceList()
  const [{ getCityListData = [] }, getCityListRequest] = useGetCityList()
  const [{ GET_PROVINCE_LIST_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [
    {
      GET_PROVINCE_LIST_ERROR, getProvinceListStatus,
      GET_CITY_LIST_ERROR, getCityListStatus,
      validatePostalCodeStatus
    },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_PROVINCE_LIST_LOADER: undefined,
        GET_CITY_LIST_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (initialRender.current) {
      initialRender.current = false
      getProvinceListRequest()
      if (!isEmpty(address) && get(address, 'province_code', '')) {
        getCityListRequest({
          province: get(address, 'province_code', '')
        })
      }
    }
  }, [
    getProvinceListRequest, GET_PROVINCE_LIST_LOADER,
    getCityListRequest, address
  ])

  const updateAddressPostalCodeError = useCallback((error) => {
    if (addrPostalSubmit.current.setState) {
      addrPostalSubmit.current.setState(({ errorField = {} }) => {
        return {
          errorField: {
            ...errorField,
            postal_code: error
          }
        }
      })
    }
  }, [])

  useEffect(() => {
    if (GET_PROVINCE_LIST_ERROR && getProvinceListStatus) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: getProvinceListStatus
        })
      }
      dispatchError(resetError({
        getProvinceListStatus: ''
      }))
    }
    if (GET_CITY_LIST_ERROR && getCityListStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getCityListStatus
      })
      dispatchError(resetError({
        getCityListStatus: ''
      }))
    }

    if (validatePostalCodeStatus === 'success' && that.current.isPostalCodeApiCall) {
      that.current.isAddressError = false
      that.current.isPostalCodeApiCall = false
      that.current.error = ''
      dispatchError(resetError({
        validatePostalCodeStatus: ''
      }))
    } else if (validatePostalCodeStatus && that.current.isPostalCodeApiCall) {
      that.current.isAddressError = true
      that.current.isPostalCodeApiCall = false
      that.current.error = validatePostalCodeStatus
      updateAddressPostalCodeError(validatePostalCodeStatus)
      dispatchError(resetError({
        validatePostalCodeStatus: ''
      }))
    }
  }, [GET_PROVINCE_LIST_ERROR, GET_CITY_LIST_ERROR,
    getCityListStatus, getProvinceListStatus,
    dispatchError, validatePostalCodeStatus, updateAddressPostalCodeError
  ])

  const handleSubmit = useCallback(async (e) => {
    const addrPostalData = await addrPostalSubmit.current.handleSubmit(e)
    if (addrPostalData && !that.current.isAddressError) {
      const finalData = {
        ...addrPostalData,
        province_name: get(addrPostalData, 'province_code_data.province_name', ''),
        city_name: get(addrPostalData, 'city_code_data.city_name', ''),
        region: get(addrPostalData, 'city_code_data.region', '')
      }
      delete finalData.errorField
      return finalData
    }
    if (that.current.isAddressError) {
      updateAddressPostalCodeError(that.current.error)
    }
  }, [updateAddressPostalCodeError])

  const handleGetAddr = useCallback(() => {
    const addr = {
      address: get(addrPostalSubmit, 'current.state.address', ''),
      province_code: get(addrPostalSubmit, 'current.state.province_code', ''),
      city_code: get(addrPostalSubmit, 'current.state.city_code', ''),
      province_name: get(addrPostalSubmit, 'current.state.province_code_data.province_name', ''),
      city_name: get(addrPostalSubmit, 'current.state.city_code_data.city_name', ''),
      postal_code: get(addrPostalSubmit, 'current.state.postal_code', ''),
      region: get(addrPostalSubmit, 'current.state.city_code_data.region', '')
    }
    return addr
  }, [addrPostalSubmit])

  const handleInputChanges = useCallback((value, type) => {
    if (type === 'postal_code' && typeValid(type, value)) {
      that.current.isPostalCodeApiCall = true
      validatePostalCodeReq({
        body: {
          postal_code: value
        }
      })
    }
    if (onAddressChange) {
      onAddressChange(handleGetAddr())
    }
  }, [onAddressChange, validatePostalCodeReq, handleGetAddr])

  const handleSelectChange = useCallback(async (value) => {
    // data from the autoSearch
    if (value.province_code) {
      getCityListRequest({ province: value.province_code })
      if (citiesRef.current) {
        await citiesRef.current.resetModalState()
        handleInputChanges()
        return
      }
    }
    return handleInputChanges()
  }, [getCityListRequest, handleInputChanges])

  useEffect(() => {
    handleGetAddressSubmit(addressType, handleSubmit, handleGetAddr)
  }, [handleSubmit, handleGetAddressSubmit,
    addressType, handleGetAddr
  ])

  return (
    <AddressFormStyle>
      <InnerForm
        formData={getAddrPostalFormData(
          {
            ...address,
            provinces: getProvinceListData,
            cities: getCityListData,
            citiesRef
          },
          labels)}
        ref={addrPostalSubmit}
        onInputChange={handleInputChanges}
        onChangeSelect={handleSelectChange}
      />
    </AddressFormStyle>
  )
}

export default AddressFormContainer
