import get from 'lodash/get'
import { ERROR_LANG, LANG_STRINGS } from '../../../lang'

export const getAddrPostalFormData = (data, labels = {}) => {
  return {
    fields: [
      {
        type: 'autoSearchModal',
        placeholder: labels.province ?? LANG_STRINGS.selectProvince,
        name: 'province_code',
        data: data.provinces,
        label: labels.province ?? LANG_STRINGS.selectProvince,
        dataKey: 'province_code',
        displayKey: 'province_name',
        defaultValue: data.province_code,
        defaultData: { province_code: data.province_name, province_name: data.province_name }
      },
      {
        type: 'autoSearchModal',
        placeholder: labels.city ?? LANG_STRINGS.selectCity,
        name: 'city_code',
        data: data.cities,
        label: labels.city ?? LANG_STRINGS.selectCity,
        dataKey: 'city_code',
        displayKey: 'city_name',
        ref: data.citiesRef,
        defaultValue: data.city_code,
        defaultData: { city_code: data.city_name, city_name: data.city_name, region: data.region }
      },
      {
        type: 'postal_code',
        label: labels.postalCode ?? LANG_STRINGS.postalCode,
        placeholder: labels.postalCode ?? LANG_STRINGS.postalCode,
        defaultValue: get(data, 'postal_code', ''),
        name: 'postal_code',
        error: ERROR_LANG.postalCodeError,
        border: true,
        className: 'input-field'
      },
      {
        type: 'textarea',
        label: labels.address ?? LANG_STRINGS.address,
        placeholder: labels.addressPlaceholder ?? '',
        defaultValue: get(data, 'address', ''),
        name: 'address',
        minLength: 10,
        maxLength: 100,
        lengthErr: ERROR_LANG.addressBetween10and100char,
        border: true,
        textAreaResize: 'vertical',
        className: 'input-field'
      }
    ]
  }
}
