import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { Container } from '../../../../../components'
import AgentAddress from '../../../../../components/AgentAddress'
import { LANG_STRINGS } from '../../../../../lang'

function AgentAddressPage (props) {
  const [{ UPDATE_AGENT_ADDRESS_LOADER }] = useLoaderContextValue()

  const handleAddressSave = useCallback(() => {
    props.history.goBack()
  }, [props.history])

  return (
    <Container
      title={LANG_STRINGS.shippingAddress}
      displayBackButton
      hideBottomTabs
      loader={UPDATE_AGENT_ADDRESS_LOADER}
    >
      <AgentAddress {...props} onAddressSave={handleAddressSave} />
    </Container>
  )
}

export default AgentAddressPage
